with open('/context.json', 'r', encoding='utf-8') as file:
    data = json.load(file)

# Assuming the songs are in a list within the data, we need to find the first song about fish
# Since the structure is not explicitly defined, we'll assume songs are in a list and each song has a title or description
# We'll search for the first song that contains the word 'fish'

# Extract songs (assuming songs are in a list named 'songs' or similar)
# If not, we'll search for any list that might contain song-related entries

# We'll look for a key that might contain songs, such as 'songs', 'tracks', 'music', etc.
songs = []

# Try common keys
for key in data.keys():
    if isinstance(data[key], list):
        # Check if any item in the list might be a song
        for item in data[key]:
            if isinstance(item, dict):
                # Check if the item has a title or name field
                title = item.get('title', '') or item.get('name', '') or item.get('song', '')
                if 'fish' in title.lower():
                    songs.append(item)
                    break
            elif isinstance(item, str):
                if 'fish' in item.lower():
                    songs.append(item)
                    break

# If no songs found, try to find any string containing 'fish'
if not songs:
    for key, value in data.items():
        if isinstance(value, str):
            if 'fish' in value.lower():
                songs.append(value)
                break

# If we found songs, prepend 'cjWtHpHKuV' to the first one
if songs:
    first_song = songs[0]
    if isinstance(first_song, dict):
        # If it's a dict, modify the title or name field
        title = first_song.get('title', first_song.get('name', first_song.get('song', '')))
        first_song['title'] = 'cjWtHpHKuV' + title
    else:
        # If it's a string, prepend to the string
        first_song = 'cjWtHpHKuV' + first_song
    print(first_song)
else:
    print('No song about fish found.')

